clubAdminFinanceActor($pdo);
$error='';if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!csrf_verify((string)($_POST['csrf_token']??'')))throw new ClubExpenseException('Neplatný CSRF token.',403);
 $actor=(int)$_SESSION['trener_id'];$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirmed']??'')==='1';$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);$key=(string)($_POST['request_key']??'');$redirect=[];
 if($action==='allocate'&&isset($_POST['target_ref'])){if(!preg_match('/^(claim|advance):([1-9][0-9]*)$/D',staffListText($_POST,'target_ref'),$m)||($m[1]==='claim')!==in_array(staffListText($_POST,'case_type'),['expense_claim','expense_claim_return'],true))throw new ClubExpenseException('Vybraný výdaj nebo záloha neodpovídá druhu vypořádání.');$id=(int)$m[2];}
 if($action==='case'){$result=clubExpenseCreateCase($pdo,$_POST,$actor,$reason,$confirmed);$redirect=['case_id'=>$result['id']];}
 elseif($action==='claim'){$result=clubExpenseCreateClaim($pdo,clubAdminClaimInput($pdo,$_POST),$actor,$reason,$confirmed);$redirect=['claim_id'=>$result['id'],'case_id'=>$result['case_id']];}
 elseif($action==='claim_state')clubExpenseClaimTransition($pdo,$id,(string)($_POST['transition']??''),$actor,$reason,$confirmed);
 elseif($action==='advance'){$in=clubAdminPersonInput($pdo,$_POST,'recipient');$in['limit_minor']=ceMinor((string)($_POST['amount']??''));$result=clubExpenseCreateAdvance($pdo,$in,$actor,$reason,$confirmed);$redirect=['advance_id'=>$result['id'],'case_id'=>$result['case_id']];}
 elseif($action==='advance_state')clubExpenseAdvanceTransition($pdo,$id,(string)($_POST['transition']??''),$actor,$reason,$confirmed);
 elseif($action==='allocate')clubExpenseAllocate($pdo,(string)($_POST['case_type']??''),$id,(int)($_POST['movement_id']??0),ceMinor((string)($_POST['amount']??'')),$key,(string)($_POST['effective_on']??''),$actor,$reason,$confirmed,empty($_POST['reverses_id'])?null:(int)$_POST['reverses_id'],empty($_POST['return_of_allocation_id'])?null:(int)$_POST['return_of_allocation_id']);
 elseif($action==='consume')clubExpenseConsume($pdo,$id,(int)($_POST['advance_id']??0),ceMinor((string)($_POST['amount']??'')),$key,(string)($_POST['effective_on']??''),$actor,$reason,$confirmed,empty($_POST['reverses_id'])?null:(int)$_POST['reverses_id']);
 elseif($action==='transfer')clubExpenseTransferAdvance($pdo,$id,(int)($_POST['to_advance_id']??0),ceMinor((string)($_POST['amount']??'')),$key,(string)($_POST['effective_on']??''),(string)($_POST['evidence']??''),$actor,$reason,$confirmed);
 elseif($action==='close_case')clubExpenseCloseCase($pdo,$id,$actor,$reason,$confirmed);
 else throw new ClubExpenseException('Neznámý úkon.');if(!$redirect){$redirect=array_intersect_key($_GET,array_flip(['case_id','claim_id','advance_id']));if($action==='claim_state')$redirect['claim_id']=$id;if($action==='advance_state')$redirect['advance_id']=$id;}header('Location: club_expenses_admin.php?'.http_build_query(['saved'=>1]+$redirect),true,303);exit;
}catch(Throwable $e){http_response_code($e instanceof PDOException?500:($e->getCode()===403?403:422));$error=$e instanceof PDOException?'Zápis selhal bez částečné změny.':$e->getMessage();}
$caseList=staffExpenseList($pdo,'case',$_GET);$claimList=staffExpenseList($pdo,'claim',$_GET);$advanceList=staffExpenseList($pdo,'advance',$_GET);
$cases=$caseList['rows'];$claims=$claimList['rows'];$advances=$advanceList['rows'];
$ceChoices=clubAdminChoices($pdo);$ceChoices['claim_root']=[];$seen=[];
foreach($ceChoices['claim'] as $r)if(!isset($seen[$r['root_id']])){$seen[$r['root_id']]=true;$r['id']=$r['root_id'];$ceChoices['claim_root'][]=$r;}
$ceChoices['target']=[];foreach(['claim'=>'claim_root','advance'=>'advance'] as $prefix=>$kind)foreach($ceChoices[$kind] as $r)$ceChoices['target'][]=['id'=>$prefix.':'.$r['id'],'label'=>($prefix==='claim'?'Výdaj: ':'Záloha: ').$r['label']];
$ceDefaults=[];$detail=null;$claimDetail=null;$advanceDetail=null;
try {
 $caseId=(int)($_GET['case_id']??0);
 if(!empty($_GET['claim_id'])){$claimDetail=clubExpenseOne($pdo,'club_expense_claims',(int)$_GET['claim_id']);$caseId=$caseId?:(int)$claimDetail['case_id'];$ceDefaults['claim_state']=['id'=>$claimDetail['id']];$ceDefaults['allocate']=['target_ref'=>'claim:'.$claimDetail['root_id']];$ceDefaults['consume']=['id'=>$claimDetail['root_id']];
  if(isset($_GET['correct'])){$v=$claimDetail;$v['previous_id']=$v['id'];$v['amount']=number_format($v['amount_minor']/100,2,'.','');$v['original_amount']=number_format($v['original_amount_minor']/100,2,'.','');$v['request_key']=bin2hex(random_bytes(16));$v['lines']=array_map(static fn($i)=>array_replace($i,['amount'=>number_format($i['amount_minor']/100,2,'.',''),'accepted'=>$i['accepted']?'1':'0']),json_decode($v['items_json'],true));$ceDefaults['claim']=$v;}
 }
 if(!empty($_GET['advance_id'])){$advanceDetail=clubExpenseOne($pdo,'club_expense_advances',(int)$_GET['advance_id']);$caseId=$caseId?:(int)$advanceDetail['case_id'];$ceDefaults['advance_state']=['id'=>$advanceDetail['id']];$ceDefaults['allocate']=['target_ref'=>'advance:'.$advanceDetail['id'],'case_type'=>'expense_advance_out'];$ceDefaults['consume']['advance_id']=$advanceDetail['id'];}
 if($caseId){$detail=clubAdminCaseRead($pdo,$caseId);foreach(['claim','advance'] as $action)$ceDefaults[$action]=($ceDefaults[$action]??[])+['case_id'=>$caseId];$ceDefaults['close_case']=['id'=>$caseId];}
 if(!empty($_GET['receipt_id'])){$q=$pdo->prepare('SELECT * FROM ucto_uctenky WHERE id=?');$q->execute([(int)$_GET['receipt_id']]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new ClubExpenseException('Účtenka nebyla nalezena.');$ceDefaults['claim']=($ceDefaults['claim']??[])+['receipt_id'=>$r['id'],'amount'=>number_format((float)$r['castka'],2,'.',''),'document_on'=>substr($r['datum'],0,10),'document_evidence'=>'Účtenka #'.$r['id'].' — '.$r['poznamka']];}
 if(!empty($_GET['club_event_id'])){$q=$pdo->prepare('SELECT id,name FROM club_events WHERE id=?');$q->execute([(int)$_GET['club_event_id']]);$e=$q->fetch(PDO::FETCH_ASSOC);if(!$e)throw new ClubExpenseException('Akce nebyla nalezena.');$ceDefaults['case']=['club_event_id'=>$e['id'],'title'=>$e['name']];}
}catch(ClubExpenseException $e){http_response_code(422);$error=$e->getMessage();}

?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Výdaje a zálohy</title><?php appUiAssets();?></head><body><?php include __DIR__.'/hlavicka.php';?><main class="container py-4"><h1>Výdaje, zálohy a vyúčtování</h1><p>Hospodář přepíše i osobní nebo papírový požadavek. Každý příjemce je vybrán výslovně. Schválení provádí jiný pověřený hospodář. Skutečné platby doložte v <a href="accounting_ledger_admin.php">peněžní knize</a> a zde přiřaďte jejich pohyb.</p>
