<details id="claim-form" open><summary>Zapsat výdaj nebo novou opravnou verzi</summary><?php ceStart('claim');ceInput('previous_id','ID předchozí vrácené nebo schválené verze (jen oprava)','number',false);ceInput('case_id','ID finančního případu','number',false);ceInput('receipt_id','ID původní účtenky se soukromou přílohou','number',false);ceInput('supplier','Dodavatel');ceInput('document_number','Číslo dokladu / papírová reference');ceInput('document_on','Datum případu','date');ceInput('due_on','Splatnost','date');ceInput('amount','Celková částka Kč');ceInput('original_currency','Původní měna','text',true,'CZK');ceInput('original_amount','Původní částka (prázdné = částka Kč)','text',false);ceInput('conversion_evidence','Doložený přepočet cizí měny','text',false);?><label>Zdroj úhrady<select name="funding_source" class="form-select"><option value="personal" <?=ceValue('funding_source','personal')==='personal'?'selected':''?>>Vlastní peníze osoby</option><option value="unpaid_supplier" <?=ceValue('funding_source')==='unpaid_supplier'?'selected':''?>>Neuhrazená dodavatelská faktura</option><option value="club" <?=ceValue('funding_source')==='club'?'selected':''?>>Klubová karta / pokladna</option><option value="advance" <?=ceValue('funding_source')==='advance'?'selected':''?>>Svěřená záloha konkrétní osoby</option></select></label><h3>Skutečný plátce</h3><?php cePerson('payer');?><h3>Věřitel / příjemce proplacení</h3><?php cePerson('creditor');ceInput('payee_evidence','Doložení příjemce a ověřeného způsobu předání');ceInput('purpose','Účel');ceInput('document_evidence','Doložení dokladu / umístění papírového originálu');ceInput('duplicate_review','Prověření případné duplicity','text',false);?><?php ceLines();?><?php ceEnd();?></details>
<details id="claim-state" ><summary>Předložit / schválit / vrátit / zamítnout verzi</summary><?php ceStart('claim_state');ceInput('id','ID konkrétní verze','number');?><select name="transition" class="form-select"><option value="submit">Předložit</option><option value="approve">Schválit</option><option value="return">Vrátit k opravě</option><option value="reject">Zamítnout</option></select><?php ceEnd();?></details>
