</main><script nonce="<?=ceH(app_csp_nonce())?>">
const lineTable=document.querySelector('#expense-lines tbody');let nextLine=Math.max(-1,...Array.from(lineTable.querySelectorAll('input[name]'),el=>Number(el.name.match(/^lines\[(\d+)\]/)?.[1]??-1)))+1;
document.querySelector('#add-expense-line').addEventListener('click',()=>{if(lineTable.rows.length>=100)return;const tpl=document.querySelector('#expense-line-template');lineTable.insertAdjacentHTML('beforeend',tpl.innerHTML.replaceAll('__INDEX__',String(nextLine++)));});
lineTable.addEventListener('click',event=>{const button=event.target.closest('[data-remove-line]');if(button)button.closest('tr').remove();});
function openExpenseSection(){if(location.hash){const target=document.getElementById(location.hash.slice(1));if(target?.tagName==='DETAILS')target.open=true;}}
window.addEventListener('hashchange',openExpenseSection);openExpenseSection();
</script></body></html>
